import sqlite3
conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row
# Search across all text columns in all tables
tables = [t['name'] for t in conn.execute(\"SELECT name FROM sqlite_master WHERE type='table'\").fetchall()]
for t in tables:
    cols = conn.execute(f'PRAGMA table_info({t})').fetchall()
    text_cols = [c['name'] for c in cols if 'TEXT' in (c['type'] or '').upper() or 'JSON' in (c['type'] or '').upper() or c['type'] == '']
    for col in text_cols:
        try:
            matches = conn.execute(f\"SELECT rowid, * FROM {t} WHERE {col} LIKE '%58410%'\").fetchall()
            if matches:
                print(f'MATCH in {t}.{col}')
                for m in matches:
                    print(f'  {dict(m)}')
        except Exception as e:
            pass
conn.close()
